data.code:
POST /users
{
  "email": "not-an-email",
  "password": "123",
  "age": 15,
  "referralCode": "XYZ123"
}

Response: 422 Unprocessable Entity
{
  "type": "https://api.example.com/errors/validation-failed",
  "title": "Validation Failed",
  "status": 422,
  "requestId": "req_validation_001",
  "errors": [
    {
      "field": "email",
      "issue": "Must be a valid email address",
      "value": "not-an-email",
      "constraint": "format:email"
    },
    {
      "field": "password",
      "issue": "Must be at least 8 characters long",
      "value": "123",
      "constraint": "minLength:8"
    },
    {
      "field": "age",
      "issue": "Must be at least 18",
      "value": 15,
      "constraint": "min:18"
    },
    {
      "field": "referralCode",
      "issue": "Referral code has expired",
      "value": "XYZ123",
      "constraint": "notExpired"
    }
  ]
}

POST /users
Accept-Language: fr-FR
{
  "email": "not-an-email"
}

Response: 422 Unprocessable Entity
{
  "type": "https://api.example.com/errors/validation-failed",
  "title": "Validation Failed",
  "status": 422,
  "errors": [
    {
      "field": "email",
      "issue": "L'adresse e-mail n'est pas valide.",
      "constraint": "format:email"
    }
  ]
}

// Client with Accept-Language: en-US sees:
// "issue": "Must be a valid email address."
